custom.expression:
let tick=floor(t*24.0);
let roll=1.0-smoothstep(0.0,0.045,abs(fract(t/8.0-p.y)-0.5));
let n=hash(vec2<f32>(floor(p.y*360.0),tick));
let q=p+vec2<f32>((n-0.5)*(0.002+roll*0.014)*cable_noise,0.0);
let wave=q.y+0.025*sin(q.x*3.0+t*0.18);
let copper=0.5+0.5*cos(floor(wave*100.0)*0.32-t*0.24);
var rgb=mix(c2,c5*0.74,copper*copper*0.82);
let h=max(-0.12-q.y,0.0);
let uv=vec2<f32>(q.x,0.43)/(h+0.035)+vec2<f32>(0.0,t*0.24);
let grid=abs(fract(uv)-0.5);
let wire=(1.0-smoothstep(0.012,0.045,min(grid.x,grid.y)))*smoothstep(0.01,0.16,h);
rgb=mix(rgb,mix(c2*0.68,c5,wire*0.7),smoothstep(0.0,0.012,h));
let cx=0.38*sin(t*0.31+0.8);
let lift=abs(sin(t*0.74));
let shadow=length((q-vec2<f32>(cx,-0.39))*vec2<f32>(1.0,4.8));
rgb=mix(rgb,c1,(1.0-smoothstep(0.0,0.21,shadow))*(0.83-0.4*lift));
let xy=q-vec2<f32>(cx,-0.235+0.25*lift);
var z=0.32;
for(var i=0;i<20;i++){
let d=length(vec3<f32>(xy,z))-0.15;
z-=clamp(d,0.0,0.09);
}
let norm=normalize(vec3<f32>(xy,max(z,0.001)));
let tile=floor(atan2(norm.z,norm.x)*1.91+t*0.52)+floor(atan2(norm.y,length(norm.xz))*2.55);
let shell=mix(c3,c4,fract(tile*0.5)*2.0);
rgb=mix(rgb,shell*(0.52+0.48*saturate(dot(norm,vec3<f32>(-0.42,0.62,0.66)))),fill(length(xy)-0.15));
let panel=q-vec2<f32>(0.0,0.32);
let box=sd_box(panel,vec2<f32>(0.544,0.096));
rgb=mix(rgb,c1*0.66,fill(box));
rgb=mix(rgb,c3,stroke(box+0.008,0.0025)*(0.6+0.4*cos(t*2.1)));
let g=(vec2<f32>(panel.x,-panel.y)+vec2<f32>(0.414,0.055))*vec2<f32>(26.5,18.0);
let col=i32(floor(g.x));
let row=i32(floor(g.y));
let b=col/4;
var w=0u;
if(row==0){if(b==0){w=0x534F4654u;}if(b==1){w=0x57415245u;}if(b==2){w=0x20464149u;}if(b==3){w=0x4C555245u;}}
if(row==1){if(b==0){w=0x47555255u;}if(b==1){w=0x204D4544u;}if(b==2){w=0x49544154u;}if(b==3){w=0x494F4E20u;}if(b==4){w=0x23303030u;}if(b==5){w=0x34000000u;}}
let a=(w>>(8u*(3u-(u32(max(col,0))&3u))))&255u;
var f=0u;
if(a==83u){f=0x74217u;}if(a==79u||a==48u){f=0x75557u;}if(a==70u){f=0x74644u;}if(a==84u){f=0x72222u;}if(a==87u){f=0x55775u;}if(a==65u){f=0x25755u;}if(a==82u){f=0x65655u;}if(a==69u){f=0x74647u;}if(a==73u){f=0x72227u;}if(a==76u){f=0x44447u;}if(a==85u){f=0x55557u;}if(a==71u){f=0x34553u;}if(a==77u){f=0x57755u;}if(a==68u){f=0x65556u;}if(a==78u){f=0x57775u;}if(a==35u){f=0x57575u;}if(a==52u){f=0x55711u;}
let u=fract(g)*vec2<f32>(4.0,7.0);
for(var i=0;i<2;i++){
let x=u.x-f32(1-i)*color_bleed*0.7;
let k=u32(max(4.0-floor(u.y),0.0))*4u+u32(max(2.0-floor(x),0.0));
if(col>=0&&x>=0.0&&x<3.0&&u.y<5.0&&((f>>k)&1u)>0u){rgb=select(c2,c3,i==1);}
}
return mix(bg,mix(rgb,c5,n*roll*cable_noise*0.16),strength);
